package run.ikaros.notes; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/private-notes/notes/{noteId}/attachments") public class PrivateAttachmentController{private final PrivateAttachmentService service;public PrivateAttachmentController(PrivateAttachmentService s){service=s;}@PostMapping public Mono<PrivateAttachmentView> attach(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID noteId,@Valid@RequestBody AttachPrivateFileRequest r){return service.attach(a,noteId,r);}@GetMapping public Flux<PrivateAttachmentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID noteId){return service.list(a,noteId);}}
